entries[17632] = { ["name"] = "Alchimistenstein", ["text"] = "Wirken in 50 sek.\nReagenzien:\nStein der Weisen , Erdsturmdiamant , Himmelsfeuerdiamant , Teufelslotus (2), Urmacht (5)\nAlchimistenstein\nWird beim Aufheben gebunden\nEinzigartigSchmuck\n+15 Stärke\n+15 Beweglichkeit\n+15 Ausdauer\n+15 Intelligenz\n+15 Willenskraft\nBenötigt Alchimie\n(350)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar." }
